<style>
:root{--ink:#142f36;--paper:#f4eddd;--green:#14665e;--rust:#a73f23;--gold:#e5b55d;--line:#d6cbb5}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Georgia,'Palatino Linotype',serif;line-height:1.5}button,input{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid var(--rust);outline-offset:4px}a{color:inherit}header,main,footer{max-width:1100px;margin:auto}nav{display:flex;justify-content:space-between;padding:20px 24px;font:12px 'Courier New',monospace;letter-spacing:1px;text-transform:uppercase}
.hero{position:relative;min-height:350px;margin:0 24px;background:#142f36;border-radius:4px;overflow:hidden;color:var(--paper)}.hero img{position:absolute;width:100%;height:100%;object-fit:cover;object-position:center}.hero:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(9,31,37,.95),rgba(9,31,37,.66) 40%,transparent 85%)}.hero-text{position:relative;z-index:1;padding:40px;max-width:535px}.eyebrow{font:12px 'Courier New',monospace;letter-spacing:2px;text-transform:uppercase;color:var(--gold)}h1{font-size:clamp(48px,8vw,85px);line-height:.95;letter-spacing:-3px;margin:22px 0}h1 i{color:var(--gold);font-weight:normal}h2{font-size:29px;line-height:1.15;margin:12px 0}.hero p{max-width:340px;font-size:17px}.ticket{display:flex;gap:12px;align-items:center;margin:26px 24px 0;padding:18px 22px;border:1px solid var(--line);border-left:7px solid var(--rust);background:#fff9ec}.ticket strong{font-size:20px}.ticket p{margin:3px 0}.layout{display:grid;grid-template-columns:340px 1fr;gap:25px;padding:25px 24px}.desk{border:1px solid var(--line);padding:24px;background:#fff9ec;box-shadow:5px 5px 0 #ded4c0}.label{font:11px 'Courier New',monospace;letter-spacing:1.6px;text-transform:uppercase}.missions{display:flex;gap:8px;margin:14px 0 22px}.missions button{width:44px;height:44px;border:1px solid var(--ink);background:transparent;border-radius:50%;font:16px 'Courier New',monospace}.missions button.active{background:var(--ink);color:var(--paper)}.missions button.done{box-shadow:inset 0 0 0 3px var(--green)}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--ink);color:#f7d595;padding:16px;font:13px/1.7 'Courier New',monospace;border-radius:3px}.routes{display:grid;gap:8px;margin:15px 0}.route{display:flex;align-items:center;gap:11px;padding:11px;border:1px solid var(--line);cursor:pointer;min-height:48px}.route:has(input:checked){border-color:var(--green);background:#e0ede3}.route input{accent-color:var(--green);width:18px;height:18px}.route span{font:13px 'Courier New',monospace}.primary,.secondary{min-height:46px;padding:10px 16px;border:1px solid var(--ink);border-radius:3px}.primary{background:var(--green);color:#fff9ec;width:100%;font-weight:bold}.secondary{background:transparent}.primary:disabled,.secondary:disabled{opacity:.5;cursor:wait}.yard-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.yard-head p{margin:0}.board{background:var(--ink);padding:22px 17px;border-radius:4px;margin-top:15px;position:relative}.yard{display:grid;grid-template-columns:repeat(12,1fr);gap:5px}.crate{aspect-ratio:1;background:#26464b;border:1px solid #62807c;border-radius:2px;display:grid;place-items:center;color:#c9d6ca;font:10px 'Courier New',monospace;position:relative}.crate.checked{background:#8c6950;color:#fff}.crate.match{background:var(--gold);border-color:#fff1cb;color:var(--ink);font-weight:bold}.crate.match:after{content:"";position:absolute;bottom:2px;width:8px;height:2px;background:var(--ink)}.legend{display:flex;gap:16px;flex-wrap:wrap;color:#e9e5d9;font:11px 'Courier New',monospace;margin:18px 0 0}.legend span:before{content:"";display:inline-block;width:9px;height:9px;background:#26464b;border:1px solid #62807c;margin-right:5px}.legend span:nth-child(2):before{background:#8c6950}.legend span:nth-child(3):before{background:var(--gold)}.track{height:20px;margin:18px 0 5px;border-bottom:4px double #8ea8a0;position:relative}.engine{position:absolute;left:0;bottom:1px;font-size:25px;line-height:1;transition:left .12s linear}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.stat{border-bottom:2px solid var(--line);padding-bottom:10px}.stat b{display:block;font:32px 'Courier New',monospace;color:var(--green)}.stat span{font:11px 'Courier New',monospace}.report{min-height:105px;border-left:3px solid var(--green);padding:8px 16px;background:#e8e8d9}.report p{margin:4px 0}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}.receipt{margin-top:18px;padding:16px;border:2px dashed var(--rust);display:none}.receipt.show{display:block}details{margin:10px 24px 25px;padding:20px;border-top:1px solid var(--line)}summary{cursor:pointer;font-weight:bold}details p{max-width:850px}footer{padding:20px 24px 40px;font-size:14px;color:#47615e}footer p{margin:5px 0}.tiny{font-size:12px;color:#536d69}.hint{font-size:14px;margin:14px 0 0}.visually-hidden{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:780px){.layout{grid-template-columns:1fr}.hero-text{padding:28px}.hero{min-height:330px}.hero:after{background:linear-gradient(90deg,rgba(9,31,37,.95),rgba(9,31,37,.35))}.ticket{align-items:flex-start}.yard{gap:4px}.crate{font-size:9px}.board{padding:16px 10px}.desk{padding:20px}}@media(prefers-reduced-motion:reduce){.engine{transition:none}}
</style>
</head>
<body>
<header><nav><a href="./">← Chloe reads Jon</a><span>Freight office № 011</span></nav>
<section class="hero"><img src="data:image/webp;base64," alt="An illustrated miniature freight depot glowing with lamplight, with a teal locomotive and colourful cargo crates"><div class="hero-text"><span class="eyebrow">A tiny database adventure</span><h1>Query<br><i>Depot.</i></h1><p>120 crates. One impatient train.<br>A good index knows where to look.</p></div></section></header>
<main>
<div class="ticket"><span aria-hidden="true" style="font-size:30px">⌁</span><div><strong>Welcome to the night shift.</strong><p>Choose a dispatch slip, pick an index, then run the search. Can you spare the clerk a walk through the entire yard?</p></div></div>
<div class="layout">
<section class="desk" aria-label="Dispatch controls"><span class="label">01 / dispatch slip</span><div class="missions" aria-label="Choose a mission"></div><span class="eyebrow" style="color:var(--rust)" id="mission-label"></span><h2 id="mission-title"></h2><p id="mission-story"></p><pre id="sql"></pre><span class="label">02 / choose your index</span><fieldset style="border:0;padding:0;margin:0"><legend class="visually-hidden">Index route</legend><div class="routes"></div></fieldset><button class="primary" id="run">Dispatch search →</button><p class="hint" id="hint"></p></section>
<section aria-label="Cargo yard"><div class="yard-head"><div><span class="label">03 / watch the work</span><p>Every square is one cargo record.</p></div><span class="label">120<br>crates</span></div><div class="board"><div class="yard" aria-hidden="true"></div><div class="track" aria-hidden="true"><span class="engine">▰</span></div><div class="legend"><span>Untouched</span><span>Inspected</span><span>Found · underlined</span></div></div>
<div class="stats"><div class="stat"><b id="inspected">0</b><span>crates inspected</span></div><div class="stat"><b id="found">0</b><span>matches loaded</span></div><div class="stat"><b id="saved">—</b><span>walks spared</span></div></div>
<div class="report" role="status" aria-live="polite"><strong id="verdict">The signal is yours.</strong><p id="explanation">Start with “No index” to see the long way round. Then try a shortcut on the same dispatch slip.</p></div><div class="actions"><button class="secondary" id="baseline">Try the full scan</button><button class="secondary" id="next">Next dispatch →</button></div><div class="receipt" id="receipt"><span class="label">All four dispatches explored</span><h2>Night shift, neatly shipped.</h2><p>Some searches need a better index. Some simply need the whole yard. Knowing the difference is the job.</p><button class="secondary" id="reset">Start a fresh shift</button></div>
<p class="tiny">Crate inspections only, not index-navigation steps or real execution time. This is a simplified read-only index model, not a live SQL database.</p></section>
</div>
<details><summary>For the curious: what is the train actually teaching?</summary><p>An index is an extra, ordered directory of column values and record locations. It helps the database avoid reading irrelevant rows. Here, each index really is built from the cargo records in your browser; the search uses its directory to select the candidate crates.</p><p>A <strong>composite index</strong> on (customer, status) groups by customer first, then status. It can narrow a search for both fields, or for customer alone. A status-only search cannot use that leading customer key to pick one contiguous range. Real databases sometimes have additional strategies, including skip scans, which this toy deliberately leaves out.</p><p>Indexes take space and must be maintained when records change. More indexes are not automatically better. We count candidate cargo records here, not tree navigation, page reads, caching, or other costs a real query planner considers.</p></details>
</main>
<footer><p>Inspired by Jon’s <a href="?source=1">Job openings at Ning.com</a>, with its call for MySQL DBAs. A small tribute to the people who keep the queries moving.</p><p>A railway metaphor for Jon and Nathan. Original depot artwork made for this page.</p></footer>
<script>
'use strict';
const $=s=>document.querySelector(s);
const customers=['Fern','Otter','Cedar','Maple','Heron','Moss'],statuses=['ready','held','shipped'];
const cargo=Array.from({length:120},(_,i)=>({id:(i*37)%120+1,customer:customers[i%6],status:statuses[Math.floor(i/6)%3],day:i%20+1}));
const indexSpecs=[{key:'none',name:'No index · walk the yard'},{key:'id',name:'INDEX (crate_id)'},{key:'customer',name:'INDEX (customer)'},{key:'both',name:'INDEX (customer, status)'},{key:'day',name:'INDEX (departure_day)'}];
const directories={};
for(const spec of indexSpecs.slice(1)){const directory=new Map();for(const row of cargo){const key=spec.key==='both'?row.customer+'|'+row.status:spec.key==='customer'?row.customer:spec.key==='day'?row.day:row.id;if(!directory.has(key))directory.set(key,[]);directory.get(key).push(row);}directories[spec.key]=directory;}
const missions=[
{title:'The missing telescope',story:'A little astronomer needs crate 73. Find that exact crate before the train leaves.',sql:'SELECT * FROM cargo\nWHERE crate_id = 73;',kind:'id',match:r=>r.id===73,hint:'A unique crate number can lead straight to one record.',explain:'The crate-ID directory points directly to the one matching record.'},
{title:'Fern’s ready-to-go parcels',story:'Fern has several parcels in the yard. Load only the ones cleared for departure.',sql:"SELECT * FROM cargo\nWHERE customer = 'Fern'\n  AND status = 'ready';",kind:'both',match:r=>r.customer==='Fern'&&r.status==='ready',hint:'One column narrows the customer. Two can narrow the customer and the status.',explain:'The two-column directory jumps to Fern’s ready group. A customer-only index still checks all of Fern’s parcels.'},
{title:'The three-day special',story:'Collect everything departing on days 7, 8, or 9. A range is not an exact match, but it still has boundaries.',sql:'SELECT * FROM cargo\nWHERE departure_day\n  BETWEEN 7 AND 9;',kind:'day',match:r=>r.day>=7&&r.day<=9,hint:'An ordered day directory lets you visit just three neighbouring groups.',explain:'The departure-day directory selects days 7 through 9, leaving the rest of the yard untouched.'},
{title:'The held-cargo surprise',story:'The manager wants every held parcel, regardless of customer. Will your two-column index still help?',sql:"SELECT * FROM cargo\nWHERE status = 'held';",kind:'status',match:r=>r.status==='held',hint:'Read the order of the two-column index carefully. Its first key is customer, not status.',explain:'None of these directories starts with status. In this simple model, every route falls back to a full scan. A new status-leading index would change that.'}
];
function plan(m,key){
if(key==='id'&&m.kind==='id')return {rows:directories.id.get(73)||[],indexed:true};
if(key==='customer'&&m.kind==='both')return {rows:directories.customer.get('Fern')||[],indexed:true};
if(key==='both'&&m.kind==='both')return {rows:directories.both.get('Fern|ready')||[],indexed:true};
if(key==='day'&&m.kind==='day')return {rows:[7,8,9].flatMap(d=>directories.day.get(d)||[]),indexed:true};
return {rows:cargo,indexed:false};
}
let current=0,busy=false,visited=new Set();
const cells=new Map();
for(const row of cargo){const el=document.createElement('span');el.className='crate';el.textContent=String(row.id).padStart(3,'0');$('.yard').append(el);cells.set(row.id,el);}
indexSpecs.forEach((spec,i)=>{const label=document.createElement('label');label.className='route';const input=document.createElement('input');input.type='radio';input.name='index';input.value=spec.key;input.checked=i===0;const text=document.createElement('span');text.textContent=spec.name;label.append(input,text);$('.routes').append(label);});
missions.forEach((m,i)=>{const b=document.createElement('button');b.textContent=i+1;b.setAttribute('aria-label','Dispatch '+(i+1)+': '+m.title);b.onclick=()=>{if(!busy){current=i;render();}};$('.missions').append(b);});
function clearYard(){for(const el of cells.values())el.className='crate';$('#inspected').textContent='0';$('#found').textContent='0';$('#saved').textContent='—';$('.engine').style.left='0%';}
function render(){const m=missions[current];$('#mission-label').textContent='Dispatch '+(current+1)+' / 4';$('#mission-title').textContent=m.title;$('#mission-story').textContent=m.story;$('#sql').textContent=m.sql;$('#hint').textContent=m.hint;[...$('.missions').children].forEach((b,i)=>{b.classList.toggle('active',i===current);b.classList.toggle('done',visited.has(i));b.setAttribute('aria-pressed',String(i===current));});clearYard();$('#verdict').textContent='The signal is yours.';$('#explanation').textContent='Pick an index and dispatch. You can replay each slip with different routes.';$('#receipt').classList.toggle('show',visited.size===4);}
function lock(value){busy=value;document.querySelectorAll('button,input').forEach(el=>el.disabled=value);}
async function dispatch(){
if(busy)return;const key=$('input[name=index]:checked').value,m=missions[current],p=plan(m,key);clearYard();lock(true);
$('#verdict').textContent=p.indexed?'Following the index directory…':'Walking the entire yard…';$('#explanation').textContent='Watch which crates the clerk has to inspect.';
let matches=0;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
try{for(let i=0;i<p.rows.length;i++){const row=p.rows[i],hit=m.match(row);cells.get(row.id).classList.add(hit?'match':'checked');if(hit)matches++;$('#inspected').textContent=i+1;$('#found').textContent=matches;$('.engine').style.left=((i+1)/p.rows.length*95)+'%';if(!reduce)await new Promise(resolve=>setTimeout(resolve,p.rows.length>30?18:55));}
const saved=120-p.rows.length;$('#saved').textContent=saved;const minimum=Math.min(...indexSpecs.map(spec=>plan(m,spec.key).rows.length));
$('#verdict').textContent=p.rows.length===minimum?(m.kind==='status'?'Full scan, for a good reason.':'A tidy dispatch!'):'Delivered. There’s a shorter route.';
$('#explanation').textContent=(p.indexed?m.explain:(key==='none'?'Without an index, the clerk inspects every record. ': 'This index does not match the leading search key, so the clerk falls back to a full scan. ')+(m.kind==='status'?m.explain:'Try another route to compare.'))+' '+matches+' matching crate'+(matches===1?'':'s')+' loaded from '+p.rows.length+' inspections.';
visited.add(current);[...$('.missions').children][current].classList.add('done');$('#receipt').classList.toggle('show',visited.size===4);
}finally{lock(false);}}
$('#run').onclick=dispatch;
$('#baseline').onclick=()=>{if(!busy){$('input[value=none]').checked=true;dispatch();}};
$('#next').onclick=()=>{if(!busy){current=(current+1)%4;render();}};
$('#reset').onclick=()=>{if(!busy){current=0;visited.clear();$('input[value=none]').checked=true;render();}};
render();
</script>
</body></html>
